<script setup lang="ts">
import projectSnapshot from '../content/projects.json';
import {covers} from '../lib/content';
import newsSnapshot from '../content/news.json';
import {computed} from 'vue';
import {usePage,usePageMeta} from '../lib/pages';
import PublicHero from '../components/PublicHero.vue';import ContentBlocks from '../components/ContentBlocks.vue';import ArticleCard from '../components/ArticleCard.vue';import LoadState from '../components/LoadState.vue';import {resource} from '../lib/resource';import {api} from '../lib/api';import type {Page,Article,Project} from '../lib/types';
const page=usePage('agl','home');const newsPage=usePage('agl','news');usePageMeta(page);const projects=resource(()=>api<Page<Project>>('/projects?limit=50'),[],projectSnapshot as unknown as Page<Project>);const section=computed(()=>page.value.sections.map(b=>{if(b.type!=='project')return b;const project=projects.data.value?.items.find(p=>p.slug===page.value.featured_project);if(!project)return b;return {...b,...(project.slug!=='rublemet'?{title:project.title,body:project.summary,image:covers[project.cover]||'',alt:project.title}:{}),links:[{label:b.links?.[0]?.label||'Открыть проект',url:'/projects/'+project.slug+'/'}]};}));const news=resource(()=>api<Page<Article>>('/news?limit=3'),[],newsSnapshot as unknown as Page<Article>);
</script><template><div class="public-home"><div class="container"><PublicHero :page="page"/><ContentBlocks :blocks="section"/><section class="latest-section" id="updates"><div class="section-heading"><div><h2>{{newsPage.title}}</h2></div><a href="/news/" class="text-link">Все публикации ↗</a></div><LoadState :stale="!!news.data.value" :loading="news.loading.value" :error="news.error.value" @retry="news.reload"><div class="news-grid"><ArticleCard v-for="article in news.data.value?.items.slice(0,3)" :key="article.id" :article="article"/></div><p v-if="!news.data.value?.items.length" class="muted">Публикации появятся здесь после выхода.</p></LoadState></section></div></div></template>
